import test from "node:test";
import assert from "node:assert/strict";
import { existsSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

type Editor = { getText(): string; handleInput(data: string): void; onSubmit?: (text: string) => void };

async function editorHarness(t: test.TestContext, powerline: Record<string, unknown>) {
  const root = mkdtempSync(join(tmpdir(), "powerline-send-delay-"));
  const previousAgentDir = process.env.PI_CODING_AGENT_DIR;
  process.env.PI_CODING_AGENT_DIR = root;
  writeFileSync(join(root, "settings.json"), JSON.stringify({ powerline: { welcome: false, ...powerline }, bashMode: { completions: false } }));
  const { default: extension } = await import("../index.ts");
  const { KeybindingsManager } = await import(new URL("../node_modules/@earendil-works/pi-coding-agent/dist/core/keybindings.js", import.meta.url).href);
  const sent: string[] = [];
  let editor!: Editor;
  const ctx = {
    cwd: root, hasUI: true, model: { name: "Test model", provider: "test" }, modelRegistry: {},
    sessionManager: { getBranch: () => [], getSessionId: () => "send-delay-test", getCwd: () => root },
    ui: {
      getEditorText: () => editor.getText(),
      setEditorComponent(factory?: (tui: object, theme: object, keys: object) => Editor) {
        if (!factory) return;
        editor = factory({ requestRender() {}, terminal: { columns: 80, rows: 24 } }, {}, KeybindingsManager.create());
        // Pi wires its submit handler onto the extension editor after the factory returns.
        editor.onSubmit = (text) => { sent.push(text); };
      },
      getEditorComponent: () => undefined,
      setStatus() {}, setWidget() {}, setFooter() {}, setHeader() {}, setWorkingMessage() {}, notify() {},
      onTerminalInput: () => () => {},
    },
  };
  const handlers = new Map<string, (event: object, context: typeof ctx) => unknown>();
  (extension as unknown as (api: object) => void)({
    on: (name: string, handler: (event: object, context: typeof ctx) => unknown) => handlers.set(name, handler),
    registerCommand() {},
    sendUserMessage() {},
    getCommands: () => [],
  });
  await handlers.get("session_start")?.({ reason: "new" }, ctx);
  t.mock.timers.enable({ apis: ["setTimeout", "setInterval", "Date"] });
  t.after(async () => {
    await handlers.get("session_shutdown")?.({ reason: "quit" }, ctx);
    t.mock.timers.reset();
    if (previousAgentDir === undefined) delete process.env.PI_CODING_AGENT_DIR;
    else process.env.PI_CODING_AGENT_DIR = previousAgentDir;
    rmSync(root, { recursive: true, force: true });
  });
  return {
    sent,
    text: () => editor.getText(),
    embedsWorkingStatus: () => Reflect.get(editor, "embedWorkingStatus"),
    type: (text: string) => { for (const char of text) editor.handleInput(char); },
    enter: () => editor.handleInput("\r"),
    escape: () => editor.handleInput("\x1b"),
    tick: (ms: number) => t.mock.timers.tick(ms),
    startCompaction: () => handlers.get("session_before_compact")?.({}, ctx),
    queued: () => {
      const inbox = join(root, "powerline-footer", "inbox.jsonl");
      return existsSync(inbox) ? readFileSync(inbox, "utf-8").split("\n").filter(Boolean).map((line) => JSON.parse(line).text) : [];
    },
  };
}

test("Esc during the send delay returns the prompt to the editor without sending it", async (t) => {
  const h = await editorHarness(t, { sendDelayMs: 4000 });
  h.type("fix the test");
  h.enter();
  assert.equal(h.text(), "");
  h.type("also lint");
  h.tick(3999);
  h.escape();
  assert.equal(h.text(), "fix the test\n\nalso lint");
  h.tick(10000);
  assert.deepEqual(h.sent, []);
});

test("delayed prompts send after the delay, or right away on Enter with an empty editor", async (t) => {
  const h = await editorHarness(t, { sendDelayMs: 4000 });
  h.type("first");
  h.enter();
  h.tick(3999);
  assert.deepEqual(h.sent, []);
  h.tick(1);
  assert.deepEqual(h.sent, ["first"]);

  h.type("second");
  h.enter();
  h.enter();
  assert.deepEqual(h.sent, ["first", "second"]);
});

for (const [compactPromptMode, sent, queued] of [
  ["queue", [], ["first", "second"]],
  ["native", ["first", "second"], []],
] as const) {
  test(`prompts sent during compaction in ${compactPromptMode} compact prompt mode`, async (t) => {
    const h = await editorHarness(t, { sendDelayMs: 4000, queue: { compactPromptMode } });
    h.type("first");
    h.enter();
    await h.startCompaction();
    h.tick(4000);
    h.type("second");
    h.enter();
    h.enter();
    assert.deepEqual(h.sent, sent);
    assert.deepEqual(h.queued(), queued);
  });
}

// Pi embeds working, compaction, summarization, and retry status in the editor
// border only when the editor opts in; otherwise it draws its own row above the bar.
for (const [workingIndicatorPlacement, embedded] of [
  ["above-powerline", false],
  // Each session_start re-reads settings, so the next editor flips back.
  [undefined, true],
  ["editor-border", true],
] as const) {
  test(`workingIndicatorPlacement ${workingIndicatorPlacement ?? "unset"} ${embedded ? "embeds" : "does not embed"} Pi's status in the editor border`, async (t) => {
    const h = await editorHarness(t, { workingIndicatorPlacement });
    assert.equal(h.embedsWorkingStatus(), embedded);
  });
}

import test from "node:test";
import assert from "node:assert/strict";
import { createRenderScheduler } from "../render-scheduler.ts";

test("render scheduler coalesces pending status renders", () => {
  const originalSetTimeout = globalThis.setTimeout;
  const callbacks: Array<() => void> = [];
  const delays: number[] = [];
  let renderCount = 0;

  globalThis.setTimeout = ((callback: () => void, delay?: number) => {
    callbacks.push(callback);
    delays.push(delay ?? 0);
    return { id: callbacks.length } as ReturnType<typeof setTimeout>;
  }) as typeof setTimeout;

  try {
    const scheduler = createRenderScheduler(() => { renderCount += 1; }, 33);

    scheduler.schedule();
    scheduler.schedule(150);
    scheduler.schedule();

    assert.equal(callbacks.length, 1);
    assert.equal(delays[0], 33);
    callbacks[0]?.();
    assert.equal(renderCount, 1);

    scheduler.schedule(150);
    assert.equal(callbacks.length, 2);
    assert.equal(delays[1], 150);
  } finally {
    globalThis.setTimeout = originalSetTimeout;
  }
});

test("render scheduler pulls pending work forward for an earlier deadline", () => {
  const originalSetTimeout = globalThis.setTimeout;
  const originalClearTimeout = globalThis.clearTimeout;
  const callbacks: Array<() => void> = [];
  const delays: number[] = [];
  const cleared = new Set<object>();
  let renderCount = 0;

  globalThis.setTimeout = ((callback: () => void, delay?: number) => {
    const handle = { id: callbacks.length + 1 };
    callbacks.push(callback);
    delays.push(delay ?? 0);
    return handle as ReturnType<typeof setTimeout>;
  }) as typeof setTimeout;
  globalThis.clearTimeout = ((handle?: ReturnType<typeof setTimeout>) => {
    if (handle && typeof handle === "object") cleared.add(handle);
  }) as typeof clearTimeout;

  try {
    const scheduler = createRenderScheduler(() => { renderCount += 1; }, 33);

    scheduler.schedule(250);
    scheduler.schedule(33);

    assert.deepEqual(delays, [250, 33]);
    assert.equal(cleared.size, 1);
    callbacks[1]?.();
    assert.equal(renderCount, 1);
  } finally {
    globalThis.setTimeout = originalSetTimeout;
    globalThis.clearTimeout = originalClearTimeout;
  }
});

test("render scheduler allows callbacks to schedule follow-up renders", () => {
  const originalSetTimeout = globalThis.setTimeout;
  const callbacks: Array<() => void> = [];
  const delays: number[] = [];
  let renderCount = 0;
  let scheduler: ReturnType<typeof createRenderScheduler>;

  globalThis.setTimeout = ((callback: () => void, delay?: number) => {
    callbacks.push(callback);
    delays.push(delay ?? 0);
    return { id: callbacks.length } as ReturnType<typeof setTimeout>;
  }) as typeof setTimeout;

  try {
    scheduler = createRenderScheduler(() => {
      renderCount += 1;
      if (renderCount === 1) {
        scheduler.schedule(150);
      }
    }, 33);

    scheduler.schedule();
    callbacks[0]?.();

    assert.equal(renderCount, 1);
    assert.equal(callbacks.length, 2);
    assert.equal(delays[1], 150);

    callbacks[1]?.();
    assert.equal(renderCount, 2);
  } finally {
    globalThis.setTimeout = originalSetTimeout;
  }
});

test("render scheduler cancels pending status renders", () => {
  const originalSetTimeout = globalThis.setTimeout;
  const originalClearTimeout = globalThis.clearTimeout;
  const callbacks: Array<() => void> = [];
  const cleared = new Set<object>();
  let renderCount = 0;

  globalThis.setTimeout = ((callback: () => void) => {
    const handle = { id: callbacks.length + 1 };
    callbacks.push(callback);
    return handle as ReturnType<typeof setTimeout>;
  }) as typeof setTimeout;
  globalThis.clearTimeout = ((handle?: ReturnType<typeof setTimeout>) => {
    if (handle && typeof handle === "object") {
      cleared.add(handle);
    }
  }) as typeof clearTimeout;

  try {
    const scheduler = createRenderScheduler(() => { renderCount += 1; }, 33);

    scheduler.schedule();
    scheduler.cancel();

    assert.equal(cleared.size, 1);
    assert.equal(renderCount, 0);
  } finally {
    globalThis.setTimeout = originalSetTimeout;
    globalThis.clearTimeout = originalClearTimeout;
  }
});

import test from "node:test";
import assert from "node:assert/strict";
import { chmodSync, existsSync, mkdirSync, mkdtempSync, readFileSync, renameSync, rmSync, statSync, utimesSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";
import { PowerlineQueueStore, currentQueueContext, formatQueueDeliveryText, parseCompactQueuedPrompt } from "../queue/store.ts";

function withStore(fn: (store: PowerlineQueueStore, dir: string) => void): void {
  const dir = mkdtempSync(join(tmpdir(), "powerline-queue-"));
  try {
    fn(new PowerlineQueueStore(join(dir, "inbox.jsonl"), join(dir, "projects.json")), dir);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

test("queue store summarizes queued and blocked prompts", () => withStore((store) => {
  const cwd = "/tmp/project-a";
  store.add({ text: "run after compact", source: { cwd, sessionId: "s1" }, target: { kind: "current-session" }, intent: "post-compact", now: 100 });
  const blocked = store.add({ text: "retry me", source: { cwd, sessionId: "s1" }, target: { kind: "project", cwd }, intent: "follow-up", now: 101 });
  store.update(blocked.id, { status: "blocked" });

  assert.deepEqual(store.summarize(currentQueueContext(cwd, "s1"), true), {
    queueCount: 2,
    blockedCount: 1,
    compacting: true,
    leadingText: "retry me",
    leadingIntent: "follow-up",
    leadingStatus: "blocked",
  });
}));

test("current-session targets stay scoped to the source session when known", () => withStore((store) => {
  store.add({ text: "session only", source: { cwd: "/tmp/project", sessionId: "s1" }, target: { kind: "current-session" }, intent: "post-compact" });
  assert.equal(store.activeItems(currentQueueContext("/tmp/project", "s1")).length, 1);
