test("unknown context estimates are event-scoped and cleared before compaction", () => {
  assert.match(source, /approximateContextUsage = event\.reason === "reload" \? estimateUnknownContextUsage\(ctx\) : null;/);
  assert.match(source, /unknownCoreFallback: approximateContextUsage,/);
  assert.match(source, /contextApproximate = coreContextUsage\?\.contextTokens === null && approximateContextUsage !== null;/);
  assert.match(source, /pi\.on\("session_before_compact", async \(_event, ctx\) => \{\r?\n\s+powerlineCompacting = true;\r?\n\s+currentCtx = ctx;\r?\n\s+isStreaming = false;\r?\n\s+liveAssistantUsage = null;\r?\n\s+approximateContextUsage = null;\r?\n\s+coreContextUsageCache\.reset\(\);/);
  assert.match(source, /pi\.on\("session_compact", async \(event, ctx\) => \{\r?\n\s+powerlineCompacting = false;\r?\n\s+currentCtx = ctx;\r?\n\s+isStreaming = false;\r?\n\s+liveAssistantUsage = null;\r?\n\s+approximateContextUsage = estimateUnknownContextUsage\(ctx\);\r?\n\s+coreContextUsageCache\.reset\(\);/);
});

import test from "node:test";
import assert from "node:assert/strict";
import { mkdtempSync, mkdirSync, readFileSync, writeFileSync, existsSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import childProcess from "node:child_process";
import { syncBuiltinESMExports } from "node:module";

import { getGitStatus, invalidateGitStatus, readOnlyGitEnv, waitForGitUpdates } from "../git-status.ts";
const completionSource = readFileSync(new URL("../bash-mode/completion.ts", import.meta.url), "utf-8");

test("read-only git commands opt out of git's optional index lock", () => {
  const env = readOnlyGitEnv({ PATH: "/usr/bin" });
  assert.equal(env.GIT_OPTIONAL_LOCKS, "0");
  assert.equal(env.PATH, "/usr/bin", "must extend the ambient environment, not replace it");
});

test("readOnlyGitEnv overrides an inherited GIT_OPTIONAL_LOCKS=1", () => {
  assert.equal(readOnlyGitEnv({ GIT_OPTIONAL_LOCKS: "1" }).GIT_OPTIONAL_LOCKS, "0");
});

test("footer git polling hides Windows child consoles while preserving read-only env", async (t) => {
  const spawn = childProcess.spawn;
  const calls: Parameters<typeof spawn>[] = [];
  t.mock.method(childProcess, "spawn", (...args: Parameters<typeof spawn>) => {
    calls.push(args);
    return spawn(...args);
  });
  syncBuiltinESMExports();
  try {
    invalidateGitStatus();
    getGitStatus("main");
    await waitForGitUpdates();
    assert.ok(calls.length > 0);
    for (const [, , options] of calls) {
      assert.equal(options?.windowsHide, true);
      assert.equal(options?.env?.GIT_OPTIONAL_LOCKS, "0");
    }
  } finally {
    t.mock.restoreAll();
    syncBuiltinESMExports();
  }
});

test("footer git polling handles a synchronous spawn failure", async (t) => {
  t.mock.method(childProcess, "spawn", () => {
    throw new Error("spawn EINVAL");
  });
  syncBuiltinESMExports();
  try {
    invalidateGitStatus();
    const cwd = mkdtempSync(join(tmpdir(), "powerline-git-spawn-"));
    const fallback = { branch: "main", staged: 0, unstaged: 0, untracked: 0 };
    assert.deepEqual(getGitStatus("main", "full", cwd), fallback);
    await assert.doesNotReject(waitForGitUpdates());
    assert.deepEqual(getGitStatus("main", "full", cwd), fallback);
  } finally {
    t.mock.restoreAll();
    syncBuiltinESMExports();
  }
});

test("bash git completions hide Windows child consoles", () => {
  assert.match(
    completionSource,
    /execFile\("git", args, \{ cwd, encoding: "utf8", signal, windowsHide: true \}/,
  );
});

// Guards the regression end to end, via a `git` shim on PATH: the footer polls
// every repo the user visits, so it must never take `.git/index.lock`.
test("the git process the footer spawns receives GIT_OPTIONAL_LOCKS=0", { skip: process.platform === "win32" ? "POSIX shim" : false }, async () => {
  const dir = mkdtempSync(join(tmpdir(), "powerline-git-locks-"));
  const bin = join(dir, "bin");
  mkdirSync(bin);
  const log = join(dir, "calls.log");

  writeFileSync(
    join(bin, "git"),
    `#!/bin/sh\necho "GIT_OPTIONAL_LOCKS=\${GIT_OPTIONAL_LOCKS-unset} ARGS=$*" >> ${JSON.stringify(log)}\nexit 0\n`,
    { mode: 0o755 },
  );

  const originalPath = process.env.PATH;
  const originalOptionalLocks = process.env.GIT_OPTIONAL_LOCKS;
  process.env.PATH = `${bin}:${originalPath ?? ""}`;
  // Some environments export GIT_OPTIONAL_LOCKS=0 as a machine-wide workaround
  // for this bug; force the opposite so we can't inherit a false pass.
  process.env.GIT_OPTIONAL_LOCKS = "1";
  try {
    invalidateGitStatus();
    getGitStatus("main");
    await waitForGitUpdates();
  } finally {
    process.env.PATH = originalPath;
    if (originalOptionalLocks === undefined) delete process.env.GIT_OPTIONAL_LOCKS;
    else process.env.GIT_OPTIONAL_LOCKS = originalOptionalLocks;
  }

  assert.ok(existsSync(log), "expected the footer to spawn git");
  const calls = readFileSync(log, "utf8").trim().split("\n");
  const status = calls.filter((line) => line.includes("ARGS=status --porcelain"));
  assert.ok(status.length > 0, `expected a status call, got:\n${calls.join("\n")}`);
  for (const call of calls) {
    assert.match(call, /GIT_OPTIONAL_LOCKS=0/, `git spawned without the lock opt-out: ${call}`);
  }
});

import test from "node:test";
import assert from "node:assert/strict";
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

type InputEvent = { type: "input"; text: string; source: string; streamingBehavior?: "steer" | "followUp" };

async function harness(t: test.TestContext, jevAnswer: () => Response) {
  const root = mkdtempSync(join(tmpdir(), "powerline-auto-follow-up-"));
  const previousAgentDir = process.env.PI_CODING_AGENT_DIR;
  const previousKey = process.env.TYPESAFE_API_KEY;
  process.env.PI_CODING_AGENT_DIR = root;
  process.env.TYPESAFE_API_KEY = "test-key";
  writeFileSync(join(root, "settings.json"), JSON.stringify({ powerline: { welcome: false, autoFollowUp: true } }));
  const requests: { state: Record<string, string> }[] = [];
  t.mock.method(globalThis, "fetch", async (_url: string, init: RequestInit) => {
    requests.push(JSON.parse(String(init.body)));
    return jevAnswer();
  });
  t.after(() => {
    if (previousAgentDir === undefined) delete process.env.PI_CODING_AGENT_DIR;
    else process.env.PI_CODING_AGENT_DIR = previousAgentDir;
    if (previousKey === undefined) delete process.env.TYPESAFE_API_KEY;
    else process.env.TYPESAFE_API_KEY = previousKey;
    rmSync(root, { recursive: true, force: true });
  });

  const { default: extension } = await import("../index.ts");
  const sent: unknown[][] = [];
  const warnings: string[] = [];
  let idle = false;
  let editorText = "";
  const run = new AbortController();
  const ctx = {
    cwd: root, hasUI: true, isIdle: () => idle, signal: run.signal,
    sessionManager: { getBranch: () => [], getSessionId: () => "auto-follow-up-test", getCwd: () => root },
    ui: {
      notify: (message: string, level: string) => { if (level === "warning") warnings.push(message); },
      setWorkingMessage() {},
      getEditorText: () => editorText,
      setEditorText: (text: string) => { editorText = text; },
    },
  };
  const handlers = new Map<string, (event: object, context: typeof ctx) => unknown>();
  (extension as unknown as (api: object) => void)({
    on: (name: string, handler: (event: object, context: typeof ctx) => unknown) => handlers.set(name, handler),
    registerCommand() {},
    sendUserMessage: (...args: unknown[]) => { sent.push(args); },
    getCommands: () => [],
  });
  await handlers.get("before_agent_start")?.({ prompt: "Fix the checkout bug" }, ctx);
  return {
    requests,
    sent,
    warnings,
    editorText: () => editorText,
    typeInEditor: (text: string) => { editorText = text; },
    pressEsc: () => { idle = true; run.abort(); },
    finishRun: () => { idle = true; },
    beforeAgentStart: (event: object) => handlers.get("before_agent_start")!(event, ctx),
    input: (event: Omit<InputEvent, "type">) => handlers.get("input")!({ type: "input", ...event }, ctx),
  };
}

const jevRoute = (choice: string, confidence: number) => () =>
  Response.json({ answers: { route: { choice, confidence } } });

test("a steered message Jev is confident can wait is queued as a follow-up", async (t) => {
  const h = await harness(t, jevRoute("follow_up", 0.95));
  const result = await h.input({ text: "What is the weather in Lisbon?", source: "interactive", streamingBehavior: "steer" });
  assert.deepEqual(result, { action: "handled" });
  assert.deepEqual(h.sent, [["What is the weather in Lisbon?", { deliverAs: "followUp" }]]);
  assert.equal(h.requests[0]?.state.current_task, "Fix the checkout bug");
  assert.equal(h.requests[0]?.state.new_message, "What is the weather in Lisbon?");
});

test("custom-message turns preserve the last user task and later user prompts still update it", async (t) => {
  const h = await harness(t, jevRoute("follow_up", 0.95));
  await h.beforeAgentStart({
    type: "before_agent_start",
    messageType: "custom",
    message: { role: "custom", customType: "subagent_complete", content: "Finished the review", display: true },
    systemPrompt: "System prompt",
  });
  await h.input({ text: "also lint", source: "interactive", streamingBehavior: "steer" });
  assert.equal(h.requests[0]?.state.current_task, "Fix the checkout bug");

  await h.beforeAgentStart({ messageType: "user", prompt: "Fix the login bug" });
  await h.input({ text: "also format", source: "interactive", streamingBehavior: "steer" });
  assert.equal(h.requests[1]?.state.current_task, "Fix the login bug");

  // Older supported Pi versions emit user events without a messageType tag.
  await h.beforeAgentStart({ prompt: "Fix the search bug" });
  await h.input({ text: "also test", source: "interactive", streamingBehavior: "steer" });
  assert.equal(h.requests[2]?.state.current_task, "Fix the search bug");
});

test("corrections and unsure answers stay as steering", async (t) => {
  for (const answer of [jevRoute("steer", 0.99), jevRoute("follow_up", 0.5)]) {
    const h = await harness(t, answer);
    const result = await h.input({ text: "Actually, preserve the public API.", source: "interactive", streamingBehavior: "steer" });
    assert.equal(result, undefined);
    assert.deepEqual(h.sent, []);
  }
});

test("Esc while Jev decides returns the messages to the editor in order instead of starting a new turn", async (t) => {
  for (const answer of [jevRoute("follow_up", 0.95), jevRoute("steer", 0.99)]) {
    const h = await harness(t, answer);
    const first = h.input({ text: "also lint", source: "interactive", streamingBehavior: "steer" });
    const second = h.input({ text: "and format", source: "interactive", streamingBehavior: "steer" });
    h.typeInEditor("draft");
    h.pressEsc();
    assert.deepEqual(await first, { action: "handled" });
    assert.deepEqual(await second, { action: "handled" });
    assert.deepEqual(h.sent, []);
    assert.equal(h.editorText(), "also lint\n\nand format\n\ndraft");
  }
});

test("a run that finishes on its own during the Jev call still delivers the message", async (t) => {
  const h = await harness(t, jevRoute("follow_up", 0.95));
  const pending = h.input({ text: "also lint", source: "interactive", streamingBehavior: "steer" });
  h.finishRun();
  assert.deepEqual(await pending, { action: "handled" });
  assert.deepEqual(h.sent, [["also lint", { deliverAs: "followUp" }]]);
  assert.equal(h.editorText(), "");
});

test("Jev failures stay as steering and say so", async (t) => {
  const h = await harness(t, () => new Response("bad key", { status: 401 }));
  assert.equal(await h.input({ text: "also lint", source: "interactive", streamingBehavior: "steer" }), undefined);
  assert.deepEqual(h.sent, []);
  assert.equal(h.warnings.length, 1);
  assert.match(h.warnings[0]!, /401.*sent as steering/);
});

test("Alt+Enter follow-ups, idle prompts, slash commands, and extension messages skip Jev", async (t) => {
  const h = await harness(t, jevRoute("follow_up", 0.95));
  const skipped: Omit<InputEvent, "type">[] = [
    { text: "later task", source: "interactive", streamingBehavior: "followUp" },
    { text: "new task", source: "interactive" },
    { text: "/compact", source: "interactive", streamingBehavior: "steer" },
    { text: "from an extension", source: "extension", streamingBehavior: "steer" },
  ];
  for (const event of skipped) assert.equal(await h.input(event), undefined);
  assert.deepEqual(h.requests, []);
  assert.deepEqual(h.sent, []);
});
